import os, re, sys, stat

def main():
    a = sys.argv[1:]
    if len(a) < 2 or not re.fullmatch(r'[0-9]+', a[1]):
        print("usage: solution.py DIR N (N a whole number >= 0)", file=sys.stderr)
        return 2
    d, n = a[0], int(a[1])
    if not os.path.isdir(d):
        print("not a directory: " + d, file=sys.stderr)
        return 1
    pat = re.compile(r'backup-[0-9]{4}-[0-9]{2}-[0-9]{2}\.tar')
    names = []
    for f in os.listdir(d):
        if pat.fullmatch(f):
            try:
                if stat.S_ISREG(os.lstat(os.path.join(d, f)).st_mode):
                    names.append(f)
            except OSError:
                pass
    names.sort()
    cut = max(len(names) - n, 0)
    out = []
    for f in names[:cut]:
        try:
            os.remove(os.path.join(d, f))
            out.append("deleted " + f)
        except OSError as e:
            print("cannot delete %s: %s" % (f, e), file=sys.stderr)
    print("\n".join(out + ["kept %d" % (len(names) - len(out))]))
    return 0

sys.exit(main())
