import sys, json


def fail(code, msg):
    print(msg, file=sys.stderr)
    sys.exit(code)


def isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def main():
    if len(sys.argv) < 3:
        fail(2, "usage: solution.py FILE THRESHOLD")
    t = sys.argv[2]
    if not (t.isascii() and t.isdigit()):
        fail(2, "THRESHOLD must be a whole number >= 0")
    thr = int(t)
    try:
        with open(sys.argv[1], encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        fail(1, "cannot read valid JSON file")
    try:
        if not isinstance(data, dict) or not isinstance(data["items"], list):
            raise ValueError
        out = []
        for p in data["items"]:
            if not isinstance(p, dict):
                raise ValueError
            md = p["metadata"]
            name, ns = md["name"], md["namespace"]
            if not isinstance(name, str) or not isinstance(ns, str):
                raise ValueError
            st = p.get("status")
            if st is None:
                st = {}
            if not isinstance(st, dict):
                raise ValueError
            cs = st.get("containerStatuses")
            if cs is None:
                cs = []
            if not isinstance(cs, list):
                raise ValueError
            total = 0
            for c in cs:
                if not isinstance(c, dict) or not isint(c["restartCount"]):
                    raise ValueError
                total += c["restartCount"]
            out.append((ns + "/" + name, total))
    except (KeyError, TypeError, ValueError):
        fail(1, "invalid pod list")
    out = [o for o in out if o[1] > thr]
    out.sort(key=lambda o: (-o[1], o[0]))
    for n, r in out:
        print(n, r)


main()
