def parse(path, d):
    with open(path, 'rb') as f:
        data = f.read()
    for line in data.split(b'\n'):
        if line.lstrip(b' \t').startswith(b'#'):
            continue
        if b'=' not in line:
            continue
        k, v = line.split(b'=', 1)
        k = k.strip(b' \t')
        if not k:
