        sys.stderr.write("usage: solution.py BASE OVERRIDE\n")
        return 2
    for p in sys.argv[1:3]:
        if not os.path.isfile(p):
            sys.stderr.write("file not found: %s\n" % p)
            return 1
    d = {}
    parse(sys.argv[1], d)
    parse(sys.argv[2], d)
    out = sys.stdout.buffer
    for k in sorted(d):
        out.write(k + b'=' + d[k] + b'\n')
