import os, sys, hashlib, stat

def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py DIR\n")
        return 2
    root = sys.argv[1]
    if not os.path.isdir(root):
        sys.stderr.write("not a directory: %s\n" % root)
        return 1
    by_size = {}
    for dp, dns, fns in os.walk(root):
        for fn in fns:
            p = os.path.join(dp, fn)
            try:
                st = os.lstat(p)
            except OSError:
                continue
            if not stat.S_ISREG(st.st_mode):
                continue
            rel = os.path.relpath(p, root).replace(os.sep, "/")
            by_size.setdefault(st.st_size, []).append((p, rel))
    groups = []
    for size, items in by_size.items():
        if len(items) < 2:
            continue
        h = {}
        for p, rel in items:
            d = hashlib.sha256()
            try:
                with open(p, "rb") as f:
                    for chunk in iter(lambda: f.read(1 << 20), b""):
                        d.update(chunk)
            except OSError:
                continue
            h.setdefault(d.digest(), []).append(rel)
        for l in h.values():
            if len(l) > 1:
                l.sort(key=lambda s: os.fsencode(s))
                groups.append(l)
    groups.sort(key=lambda l: os.fsencode(l[0]))
    out = "\n\n".join("\n".join(g) for g in groups)
    if out:
        sys.stdout.buffer.write(os.fsencode(out) + b"\n")
    return 0

sys.exit(main())
