import os, sys, hashlib, stat

def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py DIR\n")
        return 2
    root = sys.argv[1]
    if not os.path.isdir(root):
        sys.stderr.write("not a directory: %s\n" % root)
        return 1
    files = []
    def walk(d, rel):
        try:
            entries = list(os.scandir(d))
        except OSError:
            return
        for e in entries:
            r = rel + [e.name]
            try:
                if e.is_symlink():
                    continue
                if e.is_dir(follow_symlinks=False):
                    walk(e.path, r)
                elif e.is_file(follow_symlinks=False):
                    files.append((e.path, "/".join(r)))
            except OSError:
                pass
    walk(root, [])
    by_size = {}
    for p, r in files:
        try:
            by_size.setdefault(os.stat(p).st_size, []).append((p, r))
        except OSError:
            pass
    groups = []
    for size, lst in by_size.items():
        if len(lst) < 2:
            continue
        h = {}
        for p, r in lst:
            try:
                m = hashlib.sha256()
                with open(p, "rb") as f:
                    for c in iter(lambda: f.read(1 << 20), b""):
                        m.update(c)
                h.setdefault(m.digest(), []).append(r)
            except OSError:
                pass
        for g in h.values():
            if len(g) > 1:
                groups.append(sorted(g, key=lambda s: os.fsencode(s)))
    groups.sort(key=lambda g: os.fsencode(g[0]))
    out = sys.stdout.buffer
    out.write(b"\n\n".join(b"\n".join(os.fsencode(x) for x in g) for g in groups))
    if groups:
        out.write(b"\n")
    out.flush()
    return 0

sys.exit(main())
