let pat = r/^([^ ]+) +(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?$/

let num s = if s == "" then 0 else Int.of_string! s

let parse line =
  match Regex.capture pat line with
  | Some [_, name, h, m, s] ->
    if h == "" && m == "" && s == "" then None
    else Some (name, num h * 3600 + num m * 60 + num s)
  | _ -> None

