import os, sys, shutil, stat


def die(msg):
    sys.stderr.write(msg + "\n")
    sys.exit(2)


def rm(path):
    st = os.lstat(path)
    if stat.S_ISDIR(st.st_mode):
        try:
            os.chmod(path, 0o700)
        except OSError:
            pass
        for n in os.listdir(path):
            rm(os.path.join(path, n))
        os.rmdir(path)
    else:
        os.unlink(path)


def main():
    if len(sys.argv) != 2 or sys.argv[1] == "":
        die("usage: prog TARGET")
    target = sys.argv[1]
    if not os.path.isdir(target):
        die("not a directory: " + target)
    cache = os.path.join(target, "cache")
    if os.path.isdir(cache) and not os.path.islink(cache):
        names = sorted(os.listdir(os.fsencode(cache)))
        for b in names:
            rm(os.path.join(os.fsencode(cache), b))
        out = []
        for b in names:
            out.append("removed " + os.fsdecode(b))
        sys.stdout.write("".join(l + "\n" for l in out))
    else:
        print("nothing to clean")
    print("kept %d" % len(os.listdir(target)))


main()
